mapper.select:
select count(1)
from sys_student_match
where id = #{matchId}

mapper.update:
update sys_student_match
student_profile_num = #{studentProfileNum}, student_user_id_wecom = #{studentUserIdWecom}, student_name_wecom = #{studentNameWecom}, match_status = #{matchStatus}, sync_status = #{syncStatus}, error_msg = #{errorMsg}, update_time = sysdate()
